import { Component, computed, input, output } from '@angular/core';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HlmCardImports } from '@spartan-ng/helm/card';
import type { Hero } from '../../domain/hero.model';
import { PowerMeter } from '../power-meter/power-meter';

/** One hero as a card. Presentational: the hero arrives as an input and the open action leaves as an output. */
@Component({
  selector: 'app-hero-card',
  imports: [HlmAvatarImports, HlmBadgeImports, HlmButtonImports, HlmCardImports, PowerMeter],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  readonly hero = input.required<Hero>();
  readonly open = output<Hero>();

  /** Up to two initials from the hero's name, for the avatar fallback. */
  protected readonly initials = computed(() =>
    this.hero()
      .name.split(/\s+/)
      .filter(Boolean)
      .map((word) => word[0])
      .join('')
      .slice(0, 2)
      .toUpperCase(),
  );

  /** A missing hero is the one status the cards flag in the destructive colour. */
  protected readonly statusVariant = computed<'destructive' | 'secondary'>(() =>
    this.hero().status === 'MIA' ? 'destructive' : 'secondary',
  );
}
import { Component, input } from '@angular/core';
import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucideActivity, lucideTriangleAlert, lucideUserCheck, lucideZap } from '@ng-icons/lucide';
import { HlmCardImports } from '@spartan-ng/helm/card';

/** One headline figure on the dashboard. Presentational: every value arrives through an input. */
@Component({
  selector: 'app-stat-tile',
  imports: [NgIcon, HlmCardImports],
  providers: [provideIcons({ lucideActivity, lucideTriangleAlert, lucideUserCheck, lucideZap })],
  templateUrl: './stat-tile.html',
  styleUrl: './stat-tile.css',
})
export class StatTile {
  readonly label = input.required<string>();
  readonly value = input.required<number | string>();
  /** Lucide icon name for this tile. Registered above, so only the names listed there render. */
  readonly icon = input.required<string>();
  readonly detail = input('');
}
import { Component, computed, input } from '@angular/core';

/** A 0 to 100 power index drawn as a bar. Presentational: the value and label arrive as inputs. */
@Component({
  selector: 'app-power-meter',
  templateUrl: './power-meter.html',
  styleUrl: './power-meter.css',
})
export class PowerMeter {
  readonly label = input.required<string>();
  readonly value = input.required<number>();

  protected readonly clamped = computed(() => Math.min(100, Math.max(0, this.value())));
}
<div class="power-meter">
  <div class="power-meter__head">
    <span class="power-meter__label">{{ label() }}</span>
    <span class="power-meter__value">{{ clamped() }}</span>
  </div>
  <div
    class="power-meter__track"
    role="meter"
    [attr.aria-label]="label()"
    aria-valuemin="0"
    aria-valuemax="100"
    [attr.aria-valuenow]="clamped()"
  >
    <div class="power-meter__fill" [style.width.%]="clamped()"></div>
  </div>
</div>
@reference "../../../styles.css";

.power-meter { @apply grid gap-1; }
.power-meter__head { @apply flex items-center justify-between gap-2 text-xs; }
.power-meter__label { @apply text-muted-foreground; }
.power-meter__value { @apply font-medium tabular-nums; }
.power-meter__track { @apply h-2 w-full overflow-hidden rounded-full bg-muted; }
.power-meter__fill { @apply h-full rounded-full bg-primary; }
