input.content:
@reference "../../styles.css";

.hero-detail { @apply grid min-w-0 gap-6; }
.hero-detail__back { @apply justify-self-start; }

.hero-detail__header { @apply grid min-w-0 gap-4 sm:flex sm:items-start sm:justify-between; }
.hero-detail__identity { @apply flex min-w-0 items-center gap-4; }
.hero-detail__avatar { @apply size-16 shrink-0; }
.hero-detail__names { @apply grid min-w-0 gap-1; }
.hero-detail__title { @apply text-2xl font-semibold break-words; }
.hero-detail__alias { @apply text-sm text-muted-foreground; }
.hero-detail__badges { @apply flex flex-wrap items-center gap-2; }
.hero-detail__actions { @apply flex flex-wrap items-center gap-2; }

.hero-detail__tabs { @apply grid min-w-0 gap-4; }
.hero-detail__tabs-list { @apply flex w-full flex-wrap gap-1 overflow-x-auto; }
.hero-detail__panel { @apply grid min-w-0 gap-4; }

.hero-detail__overview { @apply grid grid-cols-1 gap-4 lg:grid-cols-2; }
.hero-detail__card { @apply min-w-0; }
.hero-detail__stats { @apply grid grid-cols-1 gap-3 sm:grid-cols-3; }
.hero-detail__stat { @apply grid gap-1; }
.hero-detail__stat-label { @apply text-xs text-muted-foreground; }
.hero-detail__stat-value { @apply text-xl font-semibold tabular-nums; }
.hero-detail__dossier { @apply grid grid-cols-[auto_1fr] gap-x-6 gap-y-2 text-sm; }
.hero-detail__term { @apply text-muted-foreground; }
.hero-detail__value { @apply m-0 min-w-0 break-words; }
.hero-detail__note { @apply text-sm text-muted-foreground; }

.hero-detail__form { @apply grid grid-cols-1 gap-4 sm:grid-cols-2; }
.hero-detail__field { @apply min-w-0; }
.hero-detail__input { @apply w-full min-w-0; }
.hero-detail__select { @apply w-full; }
.hero-detail__form-actions { @apply flex flex-wrap items-center justify-end gap-2 sm:col-span-2; }
.hero-detail__notice { @apply me-auto text-sm text-success; }

